import sys
from typing import List, Set, Dict
from collections import defaultdict

def get_connected_components(n: int, edges: List[tuple]) -> List[int]:
    """Find connected component sizes using Union-Find."""
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            if size[px] < size[py]:
                px, py = py, px
            parent[py] = px
            size[px] += size[py]
            return True
        return False

    for u, v in edges:
        union(u, v)

    # Collect component sizes
    components = defaultdict(int)
    for i in range(1, n + 1):
        root = find(i)
        components[root] = size[root]

    return list(components.values())

