        return "-1\n"

    # Try to form lucky numbers by merging components
    best_result = [n + 1]  # Track minimum roads needed

    # DP approach for subset sum
    min_roads = {}
    min_roads[0] = 0

    for comp_size in components:
        # Create new list to avoid modification issues
        new_roads = min_roads.copy()

        for existing_sum, roads in min_roads.items():
            new_sum = existing_sum + comp_size
            if new_sum not in lucky and new_sum >= n:
                continue

            if new_sum in min_roads:
                new_ro = roads + 1
            else:
                new_ro = 1

            if new_sum not in new_roads or new_ro < new_roads[new_sum]:
                new_roads[new_sum] = new_ro

        # Merge with old
        min_roads.update(new_roads)

    # Check which lucky numbers can be formed
    for lucky_num in lucky:
        if lucky_num in min_roads:
            roads = min_roads[lucky_num]
            if roads >= len(components) + 1:
                roads = len(components)  # Max case: merge all
            best_result[0] = min(best_result[0], roads)

    if best_result[0] > n:
