from collections import deque

class LevelGraph:
    def __init__(self, capacity):
        self.capacity = capacity  # adjacency list: capacity matrix
        self.graph = capacity
        self.flow = [[0] * len(capacity) for _ in range(len(capacity))]
        self.level = []

    def add_edge(self, u, v, cap):
        self.capacity[u][v] = cap
        if v not in [row for row in self.graph if u in row]:
            self.graph[u].append(v)
            self.graph[v].append(u)

    def bfs(self, s, t):
        self.level = [-1] * len(self.capacity)
        self.level[s] = 0
        queue = deque([s])

        while queue:
            u = queue.popleft()
            for v in self.graph[u]:
                if self.level[v] == -1 and self.capacity[u][v] > 0 and self.capacity[u][v] > self.flow[u][v]:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] != -1

    def dfs(self, u, t, pushed):
        if pushed == 0 or u == t:
            return pushed
        for v in self.graph[u]:
            if self.level[v] != self.level[u] + 1:
                continue
            tr = min(pushed, self.capacity[u][v] - self.flow[u][v])
            if tr == 0:
                continue
            push = self.dfs(v, t, tr)
            if push == 0:
                continue
            self.flow[u][v] += push
            self.flow[v][u] -= push
            return push
        return 0

    def repeat_bfs(self, s, t):
        while self.bfs(s, t):
            flow = self.dfs(s, t, float('inf'))
            if flow > 0:
                pass
        return sum(self.flow[i][j] for i in range(len(self.flow)) for j in range(len(self.flow)) if self.capacity[i][t] > 0 and self.flow[i][j] > 0)

def count_soldiers(n, m, a, b, edges):
    INF = 1000000000

    # Create a list to store the flow matrix (result)
    # flow_matrix[i][j] = number of soldiers from city i to city j
    flow_matrix = [[0] * n for _ in range(n)]

    # Create flow network
    # Nodes: 0 = source, 1..n = cities, n+1 = sink
    source = 0
    sink = n + 1
    S = [[0] * (n + 2) for _ in range(n + 2)]
    flow = [[0] * (n + 2) for _ in range(n + 2)]

    # Edges from source to each city (capacity = ai)
    for i in range(n):
        S[source][i + 1] = a[i]
        S[i + 1][source] = 0  # reverse edge

    # Edges from each city to sink (capacity = bi)
    for i in range(n):
        S[i + 1][sink] = b[i]
        S[sink][i + 1] = 0  # reverse edge

    # Edges from each city to its neighbors (including itself)
    for i in range(n):
        S[i + 1][i + 1] = a[i]  # can stay in place, up to ai soldiers
        S[i + 1][i + 1] += 0  # self edge (already counted)

    for (u, v) in edges:
        u_idx = u - 1
        v_idx = v - 1
        # Edge from city u to city v with capacity a[u]
        S[u][v] = a[u]
        # Edge from city v to city u with capacity a[v]
        S[v][u] = a[v]

    # Simplify - actually we need a graph representation for Dinic's algorithm
    adj = [[] for _ in range(n + 2)]
    for u in range(n + 2):
        for v in range(n + 2):
            if v != u and S[u][v] > 0:
                adj[u].append(v)

    # Dinic's algorithm to compute max flow
    from collections import deque

    def bfs_dinic(s, t):
        level = [-1] * (n + 2)
        level[s] = 0
        queue = deque([s])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if level[v] == -1 and S[u][v] - flow[u][v] > 0:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[t] != -1

    def dfs_dinic(u, t, pushed, level, ptr):
        if pushed == 0 or u == t:
            return pushed
        for i in range(ptr[u], len(adj[u])):
            ptr[u] = i
            v = adj[u][i]
            if level[v] != level[u] + 1 or S[u][v] - flow[u][v] <= 0:
                continue
            tr = dfs_dinic(v, t, min(pushed, S[u][v] - flow[u][v]), level, ptr)
            if tr == 0:
                continue
            flow[u][v] += tr
            flow[v][u] -= tr
            return tr
        return 0

    total_flow = 0
    while bfs_dinic(source, sink):
        ptr = [0] * (n + 2)
        while True:
            pushed = dfs_dinic(source, sink, INF, level, ptr)
            if pushed == 0:
                break
            total_flow += pushed

    # Check if total flow equals total needed (sum of b)
    total_needed = sum(b)
    if total_flow != total_needed:
        return False, None, None

    # Rebuild the flow matrix
    flow_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # If i is city (i+1) and j is city (j+1), get flow from i to j
            if i + 1 != j + 1 and S[i + 1][j + 1] > 0:
                flow_matrix[i][j] = flow[i + 1][j + 1]
            # For self (staying), we need to compute remaining soldiers
            else:
                pass

    # Actually we need to recompute flow_matrix properly
    # Soldiers from city i: either stay (flow[i+1][i+1]) or go to neighbor j
    for i in range(n):
        total_out = 0
        # Count where soldiers go
        for j in range(n):
            if i + 1 == j + 1:
                # Will compute self flow
                pass
            elif S[i + 1][j + 1] > 0:
                total_out += flow[i + 1][j + 1]

        # Soldiers staying
        staying = a[i] - total_out
        if staying < 0:
            return False, None, None
        flow_matrix[i][i] = staying

    return True, flow_matrix, S

