        if parts[0] == '2':
            if parts[1] not in friend_map:
                friend_map[parts[1]] = len(friend_names)
                friend_names.append(parts[1])

    num_friends = len(friend_names)

    # Build intervals: for each friend, which interval indices they visit
    intervals = [[] for _ in range(num_friends)]
    current_interval = 0
    first_event = True

    for i in range(1, n):
        parts = lines[i].split()
        if parts[0] == '1':
            if not first_event:
                current_interval += 1
            first_event = False
        else:
            friend_idx = friend_map[parts[1]]
            intervals[friend_idx].append(current_interval)

    # If no intervals (everyone visited in first interval), handle properly
    if len(intervals) == 0:
        return str(num_friends)

    # Build conflict matrix: conflict[i][j] = True if friends i and j share any interval
    conflict = [[False] * num_friends for _ in range(num_friends)]
    for i in range(num_friends):
        for j in range(num_friends):
            if i == j:
                continue
            # Check if they share any interval
            shared = False
            for interval_i in intervals[i]:
                if interval_i in intervals[j]:
                    shared = True
                    break
            conflict[i][j] = shared

    # Split into two halves for meet-in-the-middle
    half = num_friends // 2
    group_a = list(range(half))
    group_b = list(range(half, num_friends))

    # Enumerate independent sets for group A
    def get_independent_sets_for_group(group, conflict_matrix, num_total):
        result = {}
        n_group = len(group)
        for mask in range(1 << n_group):
            selected = set()
            valid = True
            for i, idx in enumerate(group):
                if (mask >> i) & 1:
                    # Check conflicts with other selected
                    for j, idx2 in enumerate(group):
                        if i != j and ((mask >> j) & 1) and conflict_matrix[idx][idx2]:
                            valid = False
                            break
                    if not valid:
                        break
                    selected.add(idx)
            if valid:
                result[len(selected)] = result.get(len(selected), 0) + 1
        return result if result else {0: 1}

    a_sets = get_independent_sets_for_group(group_a, conflict, num_friends)

    # For group B, find max combo with group A
    max_happy = 0

    for mask in range(1 << len(group_b)):
        b_selected = []
        valid_b = True
        for i, idx in enumerate(group_b):
            if (mask >> i) & 1:
                # Check internal conflicts
                for j, idx2 in enumerate(group_b):
                    if i != j and ((mask >> j) & 1) and conflict[idx][idx2]:
                        valid_b = False
                        break
                if not valid_b:
                    break
                b_selected.append(idx)

        if not valid_b:
            continue

        size_b = len(b_selected)

        # Check compatibility with each size from A
        for i, count_a in a_sets.items():
            valid_combo = True
            # Check if any friend in A set conflicts with B set
            for idx_a, idx_b in product(group_a, b_selected):
                if conflict[idx_a][idx_b]:
                    valid_combo = False
                    break
            if valid_combo:
                max_happy = max(max_happy, i + size_b)

    return str(max_happy)

