    d3 = ccw(p1[0], p1[1], p2[0], p2[1], p3[0], p3[1])
    d4 = ccw(p1[0], p1[1], p2[0], p2[1], p4[0], p4[1])

    if d1 == 0 and on_segment(p3[0], p3[1], p1[0], p1[1], p2[0], p2[1]):
