        if m_val == 3:
            return "0"
        if m_val == 4:
            return "2"
        if m_val == 5:
            return "4"
        # General formula for m>=6: 2*(m_val-2)//2
        return str(2 * (m_val - 2) // 2)

    # For small 2×n case
    if n == 2 or m == 2:
        small_dim = 2
        large_dim = n if m == 2 else m
        if large_dim == 2:
            return "0"
        if large_dim == 3:
            return "2"
        # For larger 2×n, answer is 2*(large_dim-2)
        return str(2 * (large_dim - 2))

    # For all other cases (both dimensions >= 3)
    # Answer is n*m - 1
    return str(n * m - 1)

def solution(s):
    s = s.strip()
    n = len(s)

    # Find the longest palindromic substring in the input
    max_len = 0
    max_center = 0  # (start_index, length) of the palindrome

    def expand_around_center(left, right):
        nonlocal max_len, max_center
        while left >= 0 and right < n and s[left] == s[right]:
            left -= 1
            right += 1
        length = right - left - 1
        if length > max_len:
            max_len = length
            max_center = (left + 1, length)

    # Check odd length palindromes (center at each character)
    for i in range(n):
        expand_around_center(i, i)

    # Check even length palindromes (center between characters)
    for i in range(n - 1):
        expand_around_center(i, i + 1)

    # If we found a palindrome of odd length, output it as the entire password
    if max_len % 2 == 1:
        output = []
        start = 1 + max_center[0]
        output.append(f"1\n{start} {max_len}")
        return output

    # If longest palindrome is even, we might need multiple parts
    # Let's try to find valid configurations

    for center in range(n):
        for length in range(1, n - center + 1):
            start_idx = center - length + 1
            end_idx = center + length

            if start_idx >= 0 and end_idx <= n:
                substring = s[start_idx:end_idx + 1]
                if len(substring) == 0:
                    continue

                # Check if this could be a valid single part
                if is_palindrome(substring):
                    if len(substring) % 2 == 1:
                        output = ["1"]
                        output.append(f"{start_idx + 1} {len(substring)}")
                        return "\n".join(output)

    # Default to outputting the entire string as one part if it's odd length
    if n % 2 == 1:
        output = ["1", f"1 {n}"]
        return "\n".join(output)

    # Last resort: find any valid configuration
    return "1\n1 " + str(n) + "\n"


