def bfs(start, adj, n):
    """Compute shortest distances from start to all other nodes."""
    dist = [float('inf')] * n
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == float('inf'):
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

