    # Start at balance 0 (offset by n)
    dp[0][OFFSET] = True

    for i in range(n):
        for bal in range(MAX_BAL):
            if not dp[i][bal]:
                continue

            current_balance = bal - OFFSET

            # Determine allowed characters
            if chars[i] == '?':
                candidates = [('W', 1), ('L', -1), ('D', 0)]
            elif chars[i] == 'W':
                candidates = [('W', 1)]
            elif chars[i] == 'L':
                candidates = [('L', -1)]
            else:
                candidates = [('D', 0)]

            for c, delta in candidates:
                new_balance = current_balance + delta
                new_bal_idx = new_balance + OFFSET

                # Violation check (except at final step)
                if i < n - 1:
                    if abs(new_balance) == k:
                        continue

                # Check bounds
                if 0 <= new_bal_idx < MAX_BAL:
                    # Valid transition
                    if not dp[i + 1][new_bal_idx]:
                        dp[i + 1][new_bal_idx] = True
                        choice[i + 1][new_bal_idx] = c
                        parent[i + 1][new_bal_idx] = (i, bal)

    # Find valid end state
    end_states = []
    for bal_idx in range(MAX_BAL):
        if dp[n][bal_idx]:
            balance = bal_idx - OFFSET
            if abs(balance) == k:
                end_states.append((balance, bal_idx))

    if not end_states:
        return "NO"

    # Choose one end state and reconstruct
    _, final_bal_idx = end_states[0]

    result = []
    for i in range(n, 0, -1):
        c = choice[i][final_bal_idx]
        result.append(c)
        prev_bal_i, prev_bal_idx = parent[i][final_bal_idx]
        if prev_bal_i is None:
            return "NO"
        final_bal_idx = prev_bal_idx

    return "".join(reversed(result))


