def solution(input_str):
    lines = input_str.strip().split('\n')

    try:
        n, m = map(int, lines[0].split())
    except:
        return "-1\n"

    # Build adjacency list (1-indexed)
    adj = [[] for _ in range(n + 1)]
    line_idx = 1

    try:
        for _ in range(m):
            if line_idx >= len(lines):
                break
            line = lines[line_idx]
            line_idx += 1
            if line.strip():
                u, v = map(int, line.split())
                adj[u].append(v)
                adj[v].append(u)
    except:
        pass

    # Get target values
    try:
        a = list(map(int, lines[line_idx].split())) if line_idx < len(lines) else [0] * n
    except:
        return "-1\n"

    a = [0] + a  # 1-indexed, but position matters for matching

    # Compute final value for each configuration
    def compute_final_values(buttons):
        values = [0] * (n + 1)
        for btn in buttons:
            values[btn] += 1
            for neighbor in adj[btn]:
                values[neighbor] += 1
        return values

    # Check if configuration wins (no counter has value == a[i])
    def is_valid(buttons):
        values = compute_final_values(buttons)
        for i in range(1, n + 1):
            if values[i] == a[i]:
                return False
        return True

    # Backtracking search for valid button set
    def dfs(idx, current_buttons):
        if idx > n:
            if is_valid(current_buttons):
                return current_buttons[:]
            return None

        # Option 1: Don't press counter idx
        result = dfs(idx + 1, current_buttons)
        if result is not None:
            return result

        # Option 2: Press counter idx
        current_buttons.append(idx)
        result = dfs(idx + 1, current_buttons)
        current_buttons.pop()
        return result

    result = dfs(1, [])

    if result is None:
        return "-1"

    return f"{len(result)}\n{' '.join(map(str, result))}\n"


