def is_valid_set_score(a, b, winner_a):
    """Check if (a, b) is a valid volleyball set score"""
    # Cannot have one team lead by more than 2 except in extended sets
    if winner_a or a > b:
        if a == 25 and b <= 23:
            return True
        if a > 25 and b >= a - 2 and b < 25:
            return True
        if a >= 15 and b >= a - 2 and a == b + 2:
            return True
    else:
        if b == 25 and a <= 23:
