    return False

def solve_set_for_total(a_points, b_points, winner_a):
    """Find all valid set scores that use exactly a_points and b_points for Team A winning"""
    result = []

    # Case 1: Team A wins in first 4 sets without tiebreak
    if a_points == 25 and b_points < 25 and a_points - b_points >= 1 and b_points <= 23:
        result.append((["25", str(b_points)], not winner_a))

    # Case 2: Team A wins 25:a where a is 23 (2 point margin)
    if a_points == 25 and b_points == 23:
        if not (a_points <= b_points + 1):
            if a_points - b_points == 2:
                if winner_a:
                    result.append((["25", str(b_points)], winner_a))
                else:
                    result.append((["str(b_points)", "25"], not winner_a))

    # Case 3: Tiebreak in first 4 sets (26:24)
    if a_points == 26 and b_points == 24:
        if winner_a:
            result.append((["26", str(b_points)], winner_a))
        else:
            result.append((["24", "26"], not winner_a))

    # Case 4: Regular set where Team A wins
    if winner_a and a_points >= 1 and b_points >= 0:
