        elif a_points >= 15 and b_points < a_points - 1:
            result.append((["str(a_points)", str(b_points)], winner_a))

    return result

MOD = 10**9 + 7

def concat_same_len(start, end, k):
    """Concatenate all numbers from start to end (inclusive) where they have the same number of digits (k digits each)."""
    if start > end:
        return 0

    d = end - start + 1  # number of terms
    # Each term j (0-indexed from left) gets multiplied by 10^{(d-1-j)*k}
    # Formula: n*10^{(d-1)k} + (n+1)*10^{(d-2)k} + ... + (n+d-1)*10^0
    # 
    # = n * 10^{(d-1)k} + 10^{(d-2)k} + (10^{(d-3)k} + 10^{(d-2)k} + ... + 10^0)
    #	= n * b^{d-1} + sum(b^{d-2}, 1) where b = 10^k
    #	= n * b^{d-1} + (b^{d-1} - 1) / (b - 1)

    b = pow(10, k, MOD)
    # Sum of geometric series 1 + b + b^2 + ... + b^{d-2} = (b^{d-1} - 1) * inv(b - 1)
    if b == 1:
        return (start * d + d * (d - 1) // 2) % MOD

    denom = (b - 1) % MOD
    inv_denom = pow(denom, MOD - 2, MOD)

    geo_sum = ((pow(b, d - 1, MOD) - 1 + MOD) * inv_denom) % MOD

    result = (start * pow(b, d - 1, MOD)) % MOD
    result = (result + geo_sum) % MOD

    return result


