                self.pos += 1
                if self.pos >= len(self.s):
                    return 0
                num2 = self.read_number()
                return self.range_concat(num1, num2)
            return num1

        if self.s[self.pos] == '(':
            self.pos += 1  # skip '('
            inner = self.parse_expr()
            if self.pos < len(self.s) and self.s[self.pos] == ')':
                self.pos += 1  # skip ')'
            return inner % MOD

        return 0

    def read_number(self):
        start_pos = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        return int(self.s[start_pos:self.pos]) % (10**9 + 8)

