        """Concatenate all integers from l to r"""
        MOD = 10**9 + 7

        if l > r:
            return 0

        start, end = l, r

        while start <= end:
            first = start
            last = min(end, (10 ** (len(str(start)))) - 1)

            if first <= last:
                result = concat_same_len(first, last, len(str(first)))
                return result

            start = last + 1

        return 0

    def combine(self, a, b):
        """Concatenate number a and b"""
        MOD = 10**9 + 7
        len_a = len(str(a))
        return (a * pow(10, len_a, MOD) + b) % MOD


