MOD = 10**9 + 7

def compute_range(start, end, length):
    """Concatenate all numbers from start to end, all having 'length' digits."""
    if start > end:
        return 0

    n = end - start + 1
    b = pow(10, length, MOD)

    if b == 1:
        return (start * n + n * (n - 1) // 2) % MOD

    denom = (b - 1) % MOD
    inv = pow(denom, MOD - 2, MOD)

    geo = ((pow(b, n - 1, MOD) - 1 + MOD) * inv) % MOD
    first_part = start * pow(b, n - 1, MOD) % MOD

    return (first_part + geo) % MOD

def solve(s):
    s = s.strip()
    i = 0

    def power10(e):
        return pow(10, e, MOD)

    def read_num():
        nonlocal i
        j = i
        while i < len(s) and s[i].isdigit():
            i += 1
        return int(s[j:i])

    def parse_expr():
        nonlocal i
        res = parse_term()
        while i < len(s) and s[i] == '+':
            i += 1
            res = (res * power10(len(str(res))) + parse_term()) % MOD
        return res

    def parse_term():
        nonlocal i
        if i >= len(s):
            return 0
        if s[i].isdigit():
            n1 = read_num()
            if i < len(s) and s[i] == '-':
                i += 1
                n2 = read_num()
                return compute_range(n1, n2, len(str(n1)))
            return n1
        if s[i] == '(':
            i += 1
            inner = parse_expr()
            i += 1  # skip ')'
            return inner % MOD
        return 0

    return str(parse_expr())

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        operations = lines[idx]
        idx += 1

        for op in operations:
            if op == 'R':
                # Shift columns right: new matrix[j] = old matrix[j+1]
                new_matrix = [[matrix[i][(j + 1) % n] for j in range(n)] for i in range(n)]
                matrix = new_matrix
            elif op == 'L':
                # Shift columns left: new matrix[j] = old matrix[j-1]
                new_matrix = [[matrix[i][(j - 1) % n] for j in range(n)] for i in range(n)]
                matrix = new_matrix
            elif op == 'D':
                # Shift rows down: new matrix[i] = old matrix[i+1]
                new_matrix = [[matrix[(i + 1) % n][j] for j in range(n)] for i in range(n)]
                matrix = new_matrix
            elif op == 'U':
                # Shift rows up: new matrix[i] = old matrix[i-1]
                new_matrix = [[matrix[(i - 1) % n][j] for j in range(n)] for i in range(n)]
                matrix = new_matrix
            elif op == 'I':
                # Replace each row with its inverse
                for i in range(n):
                    inv = [0] * (n + 1)
                    for j in range(n):
                        inv[matrix[i][j]] = j + 1
                    matrix[i] = [inv[j] for j in range(1, n + 1)]
            elif op == 'C':
                # Replace each column with its inverse
                for j in range(n):
                    inv = [0] * (n + 1)
                    for i in range(n):
                        inv[matrix[i][j]] = i + 1
                    col = [inv[j] for j in range(1, n + 1)]
                    for i in range(n):
                        matrix[i][j] = col[i]

        results.append(''.join(' '.join(map(str, row)) + '\n' for row in matrix))

