def solution(s):
    n, k = map(int, s.strip().split())

    if n <= 45:
        # For n <= 45, we can efficiently generate canonical forms
        # The number of unique canonical strings is at most 2^((n+1)//2)

        from itertools import product

        def is_canonical(S):
            """Check if S is the minimum in its equivalence class"""
            def comp(S):
                return ''.join('1' if c == '0' else '0' for c in S)

            r_S = S[::-1]
            c_S = comp(S)
            c_r_S = comp(r_S)

            return S == min([S, r_S, c_S, c_r_S])

        canonical_found = []

        # We need to check strings in lexicographic order and find their canonical form
        m = (n + 1) // 2  # Half-length for efficient generation

        def generate_and_check():
            """Generate patterns and check if they can form canonical strings"""
            for pattern_bits in range(1 << m):
                # Build the full string from pattern (positions 0..m-1)
                s = ['0'] * n

                for j in range(m):
                    if (pattern_bits >> j) & 1:
                        s[j] = '1'
                        if j != n - 1 - j:  # Not the middle character
                            s[n - 1 - j] = '1'

                    # Middle character only when n is odd
                    if j == n // 2 and n % 2 == 1:
                        s[j] = '1'

                S = ''.join(s)

                if is_canonical(S):
                    canonical_found.append(S)

        generate_and_check()

        # Sort canonical strings to get correct order
        canonical_found.sort()

        if k <= len(canonical_found):
            return canonical_found[k - 1] + '\n'
        else:
            return "-1\n"
    else:
        # For larger n, we need a smarter DP/memoization approach
        from functools import lru_cache

        def count_canonical(n):
            """Count unique canonical strings of length n"""
            @lru_cache(maxsize=None)
            def count_at(i, prefix):
                # i is current position to fill
                # prefix tracks what's been decided
                if i >= n:
                    return 1

                half = n // 2
                j = n - 1 - i  # symmetric position

                if i < half:
                    # Position i and its symmetric position j have constraints
                    return count_at(i + 1, prefix) + count_at(i + 1, prefix + '1' if i != j else '')
                else:
                    return 0

            return count_at(0, '')

        # Use brute force with optimization for large n
        # We generate canonical forms by the smaller number of unique patterns
        def generate_patterns():
            patterns = []
            m = (n + 1) // 2

            def comp(S):
                return ''.join('1' if c == '0' else '0' for c in S)

            def is_true_canonical(S):
                r_S = S[::-1]
                c_S = comp(S)
                c_r_S = comp(r_S)
                return S == min([S, r_S, c_S, c_r_S])

            for bits in range(1 << m):
                s = ['0'] * n
                for j in range(m):
                    if (bits >> j) & 1:
                        s[j] = '1'
                        s[n - 1 - j] = '1'

                    # Handle middle for odd n
                    if n % 2 == 1 and j == n // 2:
                        if not s['0']:
                            s[j] = '1'

                patterns.append(''.join(s))

            # Filter for truly canonical
            result = [p for p in patterns if is_true_canonical(p)]
            return sorted(result)

        canonical_found = generate_patterns()
        canonical_found.sort()

        if k <= len(canonical_found):
            return canonical_found[k - 1] + '\n'
        else:
